self.addEventListener('install',()=>self.skipWaiting());self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(u.origin!==self.location.origin||!u.pathname.endsWith('/native-runner.html'))return;event.respondWith((async()=>{const r=await fetch(event.request);const h=new Headers(r.headers);h.set('Cross-Origin-Opener-Policy','same-origin');h.set('Cross-Origin-Embedder-Policy','require-corp');h.set('Cache-Control','no-store');return new Response(r.body,{status:r.status,statusText:r.statusText,headers:h});})());});
